INSERT INTO policies VALUES ('billing', 'BILLING', 'Cobrança', 'Cobrança duplicada, pagamento ou fatura com contexto suficiente: financeiro, prioridade normal. Se faltar informação, revisão humana. Não executar cobrança nem estorno.', 'FINANCE', 1, TRUE);
INSERT INTO policies VALUES ('technical', 'TECHNICAL', 'Problema técnico', 'Encaminhar à equipe técnica somente com contexto suficiente. Prioridade alta exclusivamente quando há indisponibilidade que impede usar o produto. Problema não impeditivo: normal. Sem informação para distinguir: revisão humana.', 'TECHNICAL', 1, TRUE);
INSERT INTO policies VALUES ('other', 'OTHER', 'Outros e informação insuficiente', 'Casos fora das categorias ou sem dados suficientes vão para revisão humana, sem inventar prioridade ou equipe executora.', 'REVIEW', 1, TRUE);
